export function getHistoricalTeamById(teamId) {
  return historicalTeams.find((team) => team.id === teamId);
}

export function getHistoricalTeamsByClubId(clubId) {
  return historicalTeams.filter((team) => team.clubId === clubId);
}

export function getRandomHistoricalTeam() {
  return historicalTeams[Math.floor(Math.random() * historicalTeams.length)];
}

export function getRandomHistoricalTeamWithPlayers() {
  const teamsWithPlayers = historicalTeams.filter((team) => team.players.length > 0);

  if (teamsWithPlayers.length === 0) {
    return null;
  }

  return teamsWithPlayers[Math.floor(Math.random() * teamsWithPlayers.length)];
}

export function getRandomBrazilianLeagueOpponents(quantity = 19) {
  const shuffledTeams = [...historicalTeams].sort(() => Math.random() - 0.5);
  const usedClubIds = new Set();
  const selectedTeams = [];

  for (const team of shuffledTeams) {
    if (usedClubIds.has(team.clubId)) continue;

    selectedTeams.push(team);
    usedClubIds.add(team.clubId);

    if (selectedTeams.length === quantity) break;
  }

  return selectedTeams;
}
